// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { ndarray } from '@stdlib/types/ndarray';

/**
* Computes the range of a one-dimensional numeric ndarray via a callback function.
*
* @param arrays - array-like object containing an input ndarray and a callback function
* @returns range
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var ndarray = require( '@stdlib/ndarray/base/ctor' );
*
* function accessor( v ) {
*     return v * 2.0;
* }
*
* var xbuf = new Float64Array( [ -2.0, 1.0, 3.0, -5.0, 4.0, -1.0, -3.0 ] );
* var x = new ndarray( 'float64', xbuf, [ xbuf.length ], [ 1 ], 0, 'row-major' );
*
* var v = rangeBy( [ x, accessor ] );
* // returns 18.0
*/
declare function rangeBy( arrays: [ ndarray, Function ] ): number;


// EXPORTS //

export = rangeBy;
